#!/usr/bin/env bash
# install_semble.sh — fail-soft, credential-free Semble sandbox builder.

set -euo pipefail

SEMBLE_VERSION="0.1.3"
SEMBLE_SPEC="semble==${SEMBLE_VERSION}"
SEMBLE_SANDBOX_IMAGE="${SEMBLE_SANDBOX_IMAGE:-coding-workflows-semble-sandbox:0.1.3}"
# SEMBLE_PYTHON_BIN is retained as an ignored legacy input; no host Python runs.

log()
{
	printf 'install_semble: %s\n' "$*" >&2
}

write_github_env()
{
	local key="${1:?write_github_env: key required}"
	local value="${2:?write_github_env: value required}"
	if [ -n "${GITHUB_ENV:-}" ]; then
		printf '%s=%s\n' "${key}" "${value}" >> "${GITHUB_ENV}" 2>/dev/null || log "unable to write ${key} to GITHUB_ENV; continuing."
	fi
}

mark_available()
{
	write_github_env "SEMBLE_SANDBOX_IMAGE_ID" "$1"
	write_github_env "SEMBLE_AVAILABLE" "true"
	log "Semble ${SEMBLE_VERSION} sandbox is available."
}

mark_unavailable()
{
	write_github_env "SEMBLE_AVAILABLE" "false"
	log "Semble ${SEMBLE_VERSION} sandbox unavailable; callers should use fallback paths."
}

write_semble_sandbox_context()
{
	local context_dir="$1"
	cat > "${context_dir}/Dockerfile" <<'DOCKERFILE'
FROM python:3.12.12-slim-bookworm@sha256:593bd06efe90efa80dc4eee3948be7c0fde4134606dd40d8dd8dbcade98e669c
COPY requirements.lock semble_index.py semble_query.py /opt/semble/
RUN pip install --no-cache-dir --require-hashes --no-deps --only-binary=:all: -r /opt/semble/requirements.lock && mkdir /index
ENV PYTHONDONTWRITEBYTECODE=1 HF_HUB_OFFLINE=1 HOME=/tmp
USER 65534:65534
LABEL org.coding-workflows.semble.version="0.1.3"
DOCKERFILE
	# Generated with uv pip compile --no-config --default-index https://pypi.org/simple
	# --generate-hashes --python-version 3.12 --python-platform x86_64-manylinux_2_28
	# --only-binary :all: from the sole input semble==0.1.3. Full wheel hash set
	# allows pip to select the compatible wheel on the pinned amd64 image.
	cat > "${context_dir}/requirements.lock" <<'LOCK'
anyio==4.15.1 --hash=sha256:6152fdbbf9a77fdec97731721bebf7c4c44f7c29b424b0065826173efc7ed101 --hash=sha256:9f28306018cbd6d329e64a36d58256edff76dd996fe423bc957326e578b82a94
