	cat > "${context_dir}/semble_index.py" <<'PY'
import pickle
import sys
from pathlib import Path

import bm25s
from semble.index.chunker import chunk_source
from semble.index.file_walker import filter_extensions, language_for_path, walk_files
from semble.index.sparse import enrich_for_bm25
from semble.tokens import tokenize
from semble.version import __version__ as semble_version

repo_root = Path(sys.argv[1]).resolve()
index_path = Path(sys.argv[2])
extensions = filter_extensions(None, include_text_files=True)
MAX_INDEX_FILES = 5000
chunks = []
indexed_files = 0

for file_path in walk_files(repo_root, extensions, None):
    indexed_files += 1
    if indexed_files > MAX_INDEX_FILES:
        raise SystemExit(
            f"Semble indexing skipped after {MAX_INDEX_FILES} files; continuing without Semble."
        )
    try:
        source = file_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        continue
    rel_path = file_path.resolve().relative_to(repo_root)
    chunks.extend(chunk_source(source, str(rel_path), language_for_path(file_path)))

if not chunks:
    raise SystemExit("No supported files found for Semble indexing.")

bm25_index = bm25s.BM25()
bm25_index.index([tokenize(enrich_for_bm25(chunk)) for chunk in chunks], show_progress=False)

index_path.parent.mkdir(parents=True, exist_ok=True)
with index_path.open("wb") as handle:
    pickle.dump(
        {"version": semble_version, "chunks": chunks, "bm25_index": bm25_index},
        handle,
        protocol=pickle.HIGHEST_PROTOCOL,
    )
PY
	cat > "${context_dir}/semble_query.py" <<'PY'
import argparse
import pickle
import sys


def _query(argv):
    parser = argparse.ArgumentParser(prog="semble query")
    parser.add_argument("--index", required=True)
    parser.add_argument("--top-k", type=int, default=5)
    parser.add_argument("--format", default="text")
    if len(argv) < 2 or argv[0] != "--":
        return 2
    query_text = argv[1]
    args = parser.parse_args(argv[2:])
    if args.format != "text":
        print("semble wrapper supports only --format text", file=sys.stderr)
        return 2
    try:
        from semble.search import search_bm25
        with open(args.index, "rb") as handle:
            payload = pickle.load(handle)
        results = search_bm25(query_text, payload["bm25_index"], payload["chunks"], args.top_k, selector=None)
    except Exception as exc:
        print(f"Semble query failed: {type(exc).__name__}", file=sys.stderr)
        return 1
    for idx, result in enumerate(results, start=1):
        chunk = result.chunk
        if idx > 1:
            print()
        print(f"[{idx}] {chunk.file_path}:{chunk.start_line}-{chunk.end_line}")
        print(chunk.content.rstrip("\n"))
    return 0


if __name__ == "__main__":
    if len(sys.argv) < 2 or sys.argv[1] != "query":
        raise SystemExit(2)
    raise SystemExit(_query(sys.argv[2:]))
PY
}

build_semble_sandbox_image()
{
	local context_dir="" image_id=""
	log "Building ${SEMBLE_SPEC} in a credential-free image."
	if ! command -v docker >/dev/null 2>&1 || ! command -v timeout >/dev/null 2>&1; then
		return 1
	fi
	context_dir="$(mktemp -d)" || return 1
	chmod 0700 "${context_dir}" || { rm -rf -- "${context_dir}"; return 1; }
	# Only fixed heredocs enter docker build; never pass the caller's env or repo.
	if ! write_semble_sandbox_context "${context_dir}" \
		|| ! timeout --kill-after=10s 900s env -i PATH="${PATH}" HOME="${HOME:-/tmp}" \
			docker build -q -t "${SEMBLE_SANDBOX_IMAGE}" "${context_dir}" >/dev/null; then
		rm -rf -- "${context_dir}"
		return 1
	fi
	rm -rf -- "${context_dir}"
	image_id="$(env -i PATH="${PATH}" HOME="${HOME:-/tmp}" docker image inspect --format '{{.Id}}' "${SEMBLE_SANDBOX_IMAGE}" 2>/dev/null)" || return 1
	[[ "${image_id}" =~ ^sha256:[a-f0-9]{64}$ ]] || return 1
	mark_available "${image_id}"
}

main()
{
	if [ -n "${SEMBLE_PYTHON_BIN:-}" ]; then
		log "SEMBLE_PYTHON_BIN is ignored; the host Python interpreter is not used."
	fi
	if ! build_semble_sandbox_image; then
		mark_unavailable
	fi
	return 0
}

main "$@"
